def optimized_op(gate, up):
    if hasattr(gate, "matmul"):
        import torch.nn.functional as F

        return F.silu(gate) * up
    else:
        import numpy as np

        silu_gate = gate / (1.0 + np.exp(-gate))
        return silu_gate * up

