import torch

def optimized_op(ba):
    if hasattr(ba, "chunk"):
        b, a = ba.chunk(2, dim=-1)
        return b.contiguous(), a.contiguous()
    else:
        half = ba.shape[-1] // 2
        return ba[:, :half], ba[:, half:]
